import { z } from 'zod';

type SemanticToolCallExtra = {
    signal?: AbortSignal;
};

type SemanticToolError = {
    code: string;
    message: string;
    details?: Record<string, unknown> | null;
    docsUrl?: string | null;
};

type SemanticToolCallResult = {
    content: Array<{
        type: "text";
        text: string;
    }>;
    structuredContent: {
        ok: boolean;
        data?: unknown;
        error?: SemanticToolError;
    };
    isError?: boolean;
};

type SemanticToolName = "list_workflows" | "run_workflow" | "list_runs" | "get_run" | "watch_run" | "explain_run" | "list_pending_approvals" | "resolve_approval" | "ask_human" | "get_node_detail" | "revert_attempt" | "fork_run" | "replay_run" | "rewind_run" | "restore_checkpoint" | "list_snapshots" | "get_timeline" | "time_travel" | "list_artifacts" | "get_chat_transcript" | "get_run_events";

type SemanticToolDefinition = {
    name: SemanticToolName;
    description: string;
    inputSchema: z.ZodTypeAny;
    outputSchema: z.ZodTypeAny;
    annotations: Record<string, boolean>;
    handler: (input: any, extra?: SemanticToolCallExtra) => Promise<SemanticToolCallResult>;
};

export type { SemanticToolName as S, SemanticToolDefinition as a, SemanticToolCallExtra as b, SemanticToolCallResult as c };
